#include "thermal_policy.hpp"
#include <algorithm>
#include <jni.h>
namespace ugts41::android {namespace {struct Env{JavaVM*vm;JNIEnv*e=nullptr;bool detach=false;explicit Env(ANativeActivity*a):vm(a->vm){if(vm->GetEnv(reinterpret_cast<void**>(&e),JNI_VERSION_1_6)!=JNI_OK){if(vm->AttachCurrentThread(reinterpret_cast<JNIEnv**>(&e),nullptr)==JNI_OK)detach=true;else e=nullptr;}}~Env(){if(detach)vm->DetachCurrentThread();}};}
int query_thermal_status(android_app*app){if(!app||!app->activity)return 0;Env x(app->activity);if(!x.e)return 0;auto ac=x.e->GetObjectClass(app->activity->clazz);auto gm=x.e->GetMethodID(ac,"getSystemService","(Ljava/lang/String;)Ljava/lang/Object;");auto pn=x.e->NewStringUTF("power");auto mgr=gm?x.e->CallObjectMethod(app->activity->clazz,gm,pn):nullptr;x.e->DeleteLocalRef(pn);int result=0;if(mgr){auto mc=x.e->GetObjectClass(mgr);auto gs=x.e->GetMethodID(mc,"getCurrentThermalStatus","()I");if(gs)result=x.e->CallIntMethod(mgr,gs);x.e->DeleteLocalRef(mc);x.e->DeleteLocalRef(mgr);}x.e->DeleteLocalRef(ac);if(x.e->ExceptionCheck()){x.e->ExceptionClear();result=0;}return result;}
ThermalTuning thermal_tuning(const RuntimeProfile&p,int status){ThermalTuning t;t.status=status;t.process_fps=p.camera_fps;t.feature_budget=p.features.feature_budget;t.thumbnails=p.storage_mode==StorageMode::SeedDeltasAndThumbnail;if(status>=5){t.pause_capture=true;t.process_fps=5;t.feature_budget=24;t.thumbnails=false;}else if(status>=4){t.process_fps=10;t.feature_budget=40;t.thumbnails=false;}else if(status>=3){t.process_fps=15;t.feature_budget=64;t.thumbnails=false;}else if(status>=2){t.process_fps=24;t.feature_budget=std::min<std::uint16_t>(t.feature_budget,80);t.thumbnails=false;}return t;}
}
